      SUBROUTINE FITCHKCC     DETERMINES IF VARIED ELEMENTS ARE USEDC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2B.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0D.CIN'      INCLUDE 'ELM0F.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM24A.CIN'      INCLUDE 'ELM31A.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'VFLAG.CIN'C---------------------------------------------------------------      EXTERNAL      IDATAC      CALL FILL23C      NUM = 1      NDIF = 1      ATWORK = NUSE .EQ. 0      MKG = .FALSE.      NV1 = 0C    1 I = ISTOR(NUM)      TYPE = IDATA(I)      IF (TYPE .LE. 0 .OR. TYPE .GE. 50) GO TO 5200      CALL SKETCH(NUM)      NCT = NCT + 1      CALL DEPICT      IF (.NOT. ATWE) GO TO 5200      IF (TYPE .EQ. 1) GO TO 5000      IF (TYPE .EQ. 2) GO TO 5000      IF (TYPE .EQ. 3) GO TO 5000      IF (TYPE .EQ. 4) GO TO 5000      IF (TYPE .EQ. 5) GO TO 5000      IF (TYPE .EQ. 7) GO TO 5000      IF (TYPE .EQ. 8) GO TO 5000      IF (TYPE .EQ. 12) GO TO 5000      IF (TYPE .EQ. 14) GO TO 5000      IF (TYPE .EQ. 16) GO TO 1600      IF (TYPE .EQ. 18) GO TO 5000      IF (TYPE .EQ. 19) GO TO 5000      IF (TYPE .EQ. 20) GO TO 5000      IF (TYPE .EQ. 24) GO TO 2400      IF (TYPE .EQ. 25) GO TO 5000      IF (TYPE .EQ. 27) GO TO 5000      IF (TYPE .EQ. 28 .OR. TYPE .EQ. 29) GO TO 5000      IF (TYPE .EQ. 30) GO TO 5000      IF (TYPE .EQ. 34) GO TO 5000      IF (TYPE .EQ. 35 .OR. TYPE .EQ. 36) GO TO 5000      IF (TYPE .EQ. 42) GO TO 5000      GO TO 5200C 1600 NPARS = INT(DATA(I+1))      GO TO 5000C 2400 JDEF = IDATA(I+1)      IF (JDEF .EQ. 3 .OR. JDEF .EQ. 4) THEN        NADDEF(1) = IDATA(I+2)        NADDEF(2) = IDATA(I+3)      ENDIF      CALL DEFINE      GO TO 5200C 5000 NVTYPE = NV(TYPE)      IF (NVTYPE .EQ. 0) GO TO 5200      DO 5050 JV = 1, NVTYPE      IPT = IPTOJ(JV)      IF (IPT .EQ. 0) GO TO 5050      IADR = I + IPT 5010 ISIG = IABS(TIE(IADR))      IVARY = ISIG      IF (IVARY .NE. 0 .AND. IVARY .LE. NPVAR) IVARY = VSTOR(IVARY)      IF (IVARY .GE. 2 .AND. IVARY .LE. 50) VFLAG = .TRUE.      IF (ISIG .NE. 0 .AND. ISIG .LE. NPVAR) GO TO 5040      IF (ISIG .EQ. 100) THEN        IADR = IDATA(IADR)        GO TO 5010      ENDIF      IF (ISIG .EQ. 99) THEN        ISIG = 0        DO 5020 K = 1, NPVAR        REF = DATA(IADR + K)        IF (REF .GT. 0.5) ISIG = MAX0(ISIG,K) 5020   CONTINUE      ENDIF 5040 IF (ISIG .GT. NV1) NV1 = ISIG 5050 CONTINUEC 5200 NUM = NUM + NDIF      IF (NUM .LE. NEL) GO TO 1      RETURN      END